// Renders {{call_when}} / {{call_when_short}} per MESSAGE_TEMPLATES.md.
//
// The call time is rendered in the LEAD'S timezone, not Kasper's. Telling
// someone in Los Angeles their call is at 3:45pm when they booked 12:45pm
// their time is the fastest way to lose the call. iClosed knows the invitee
// timezone; pass it through from the router.
const DEFAULT_TZ = 'America/New_York';
const out = [];

function validTz(tz) {
  if (!tz) return null;
  try { new Date().toLocaleString('en-US', { timeZone: tz }); return tz; }
  catch (e) { return null; }
}

// 3:45pm / 3pm — lowercase, no leading zero, drop :00 on the hour.
function timeLabel(d, tz) {
  const s = d.toLocaleString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: tz });
  return s.replace(/\s/g, '').replace(':00', '').toLowerCase();
}

// Calendar-day difference in the target timezone, not a 24h-bucket count:
// a call 20 hours away can still be "today" or already "tomorrow".
function dayKey(d, tz) {
  return d.toLocaleDateString('en-CA', { timeZone: tz });
}
function daysBetween(a, b, tz) {
  return Math.round((Date.parse(dayKey(b, tz) + 'T00:00:00Z') - Date.parse(dayKey(a, tz) + 'T00:00:00Z')) / 86400000);
}

for (const item of $input.all()) {
  const j = item.json || {};
  const first = String(j.first_name || '').trim();

  let phone = String(j.phone || '').replace(/[^0-9+]/g, '');
  if (phone && !phone.startsWith('+')) {
    const d = phone.replace(/\+/g, '');
    if (d.length === 10) phone = '+1' + d;
    else if (d.length === 11 && d.startsWith('1')) phone = '+' + d;
    else phone = '';
  }
  if (phone && !/^\+[1-9][0-9]{7,14}$/.test(phone)) phone = '';

  const start = new Date(j.call_start_iso);
  const tzGiven = validTz(j.timezone);
  const tz = tzGiven || DEFAULT_TZ;
  // If we had to guess the timezone, say so rather than state a wrong time.
  const suffix = tzGiven ? '' : ' ET';

  let callWhen = '';
  let callWhenShort = 'then';
  if (!isNaN(start)) {
    const t = timeLabel(start, tz) + suffix;
    const delta = daysBetween(new Date(), start, tz);
    if (delta <= 0) { callWhen = 'today at ' + t; callWhenShort = 'later today'; }
    else if (delta === 1) { callWhen = 'tomorrow at ' + t; callWhenShort = 'tomorrow'; }
    else if (delta <= 6) {
      const wd = start.toLocaleDateString('en-US', { weekday: 'long', timeZone: tz });
      callWhen = wd + ' at ' + t; callWhenShort = wd;
    } else {
      const dl = start.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', timeZone: tz });
      callWhen = dl + ' at ' + t; callWhenShort = 'then';
    }
  }

  const nameOk = first.length >= 2 && !/[0-9@]/.test(first);
  const salutation = nameOk
    ? 'Hi ' + first + ", it's Kasper from Synchro Social"
    : "Hi, it's Kasper from Synchro Social";

  out.push({ json: {
    lead_key: String(j.email || '').trim().toLowerCase() || phone,
    phone,
    salutation,
    call_when: callWhen,
    call_when_short: callWhenShort,
    // No phone, or an unparseable time, means no message. A confirmation that
    // says "your call is at " is worse than no confirmation.
    sendable: !!phone && !!callWhen
  } });
}

return out;
